package docker

// minShortIDLen is the length of the short container ID printed by `docker ps`.
// maxIDLen is the length of a full SHA-256 container ID.
const (
	minShortIDLen = 12
	maxIDLen      = 64
)

// IsContainerID reports whether s is a well-formed Docker container ID:
// a lowercase hexadecimal string of 12 to 64 characters.
//
// Container IDs are parsed from `docker ps` output and are later embedded in
// shell command lines by the log and inspect pagers. Validating them keeps shell
// metacharacters out of those command lines even if the parsing ever drifts.
func IsContainerID(s string) bool {
	if len(s) < minShortIDLen || len(s) > maxIDLen {
		return false
	}
	for _, r := range s {
		isHex := (r >= '0' && r <= '9') || (r >= 'a' && r <= 'f')
		if !isHex {
			return false
		}
	}
	return true
}
package docker

import "log"

// ImageNames names the images present on this machine, and says whether it
// could find out.
//
// The second return is the whole point. "Docker is not running" and "the image
// is gone" are the same silence from a caller's side, and reading the first as
// the second would empty every cache reader of its images the moment the daemon
// stops. A failed enumeration keeps everything instead: showing a target that no
// longer exists is a stale row, hiding one that does is a lie.
//
// It is a **var**, and that is the test seam three packages were each declaring
// for themselves. A test cannot pull an image, so without it a reconciliation
// could only be asserted by checking that a fixture happens to be absent — which
// it would pass for the wrong reason. Production never reassigns it.
var ImageNames = func() (map[string]struct{}, bool) {
	list, err := ListImages()
	if err != nil {
		log.Printf("INFO [docker] image list unavailable, keeping every cached image: %v", err)
		return nil, false
	}
	names := make(map[string]struct{}, len(list))
	for _, img := range list {
		names[img.Name()] = struct{}{}
	}
	return names, true
}
package docker

import (
	"strconv"
	"strings"
)

// OCIStats contains OCI resource counts and disk usage
type OCIStats struct {
	Available       bool
	ImagesCount     int
	ImagesSize      string
	ContainersCount int
	ContainersSize  string
	VolumesCount    int
	VolumesSize     string

	// NetworksCount does **not** come from `docker system df`, which has no row
	// for networks: they hold no bytes, so the disk report ignores them. It is
	// counted by a separate `docker network ls`, and it is the only figure in
	// this struct that costs a second call.
	NetworksCount int

	// BuildCacheSize is the fourth row `docker system df` prints, and the one
	// that answers "where did the disk go" most often — a build cache commonly
	// reaches tens of gigabytes. It was already part of the reclaimable sum;
	// only its own size used to be discarded.
	BuildCacheSize string

	// Reclaimable is what `docker system df` already reports and this package
	// used to drop on the floor: the space a prune would free, summed across
	// the three families. Docker gives it as "12.3GB (45%)" — only the size
	// is kept, the percentage is relative to its own family and would make no
	// sense once added up.
	Reclaimable string
}

// FetchOCIStats returns OCI resource counts and disk usage via docker system df
func FetchOCIStats() OCIStats {
	stats := OCIStats{}

	if runner.LookPath() != nil {
		return stats
	}

	output, err := dockerOutput("system", "df", "--format",
		"{{.Type}}\t{{.TotalCount}}\t{{.Size}}\t{{.Reclaimable}}")
	if err != nil {
		return stats
	}

	stats.Available = true
	var reclaimable int64

	for _, line := range splitLines(output) {
		parts := strings.SplitN(line, "\t", 4)
		if len(parts) < 3 {
			continue
		}
		count, _ := strconv.Atoi(parts[1])
		size := parts[2]
		if len(parts) >= 4 {
			// "12.3GB (45%)" — the percentage is relative to its own family
			// and would not survive an addition.
			reclaimable += parseSize(strings.TrimSpace(strings.Split(parts[3], "(")[0]))
		}

		switch parts[0] {
		case "Images":
			stats.ImagesCount = count
			stats.ImagesSize = size
		case "Containers":
			stats.ContainersCount = count
			stats.ContainersSize = size
		case "Local Volumes":
			stats.VolumesCount = count
			stats.VolumesSize = size
		case "Build Cache":
			stats.BuildCacheSize = size
		}
	}

	if reclaimable > 0 {
		stats.Reclaimable = formatSize(reclaimable)
	}

	// A list that fails leaves the count at zero rather than failing the
	// whole call: the sizes were just read and are worth returning.
	if networks, err := ListNetworks(); err == nil {
		stats.NetworksCount = len(networks)
	}

	return stats
}
package docker

import (
	"context"
	"fmt"
	"os/exec"
	"strings"
)

// dockerCmd describes one CLI invocation.
type dockerCmd struct {
	// Args are passed to the binary verbatim, e.g. {"ps", "--format", "..."}.
	Args []string
	// Stdin is written to the process when non-empty. Used to keep secrets out
	// of the process list (`docker login --password-stdin`).
	Stdin string
	// Combined merges stderr into the returned bytes. Docker writes failure
	// detail to stderr, so mutating calls set this to produce a usable message;
	// calls that parse stdout leave it false.
	Combined bool
	// Helper runs `docker-credential-<Helper>` instead of `docker`.
	Helper string
	// Ctx kills the process when it is cancelled. Nil for the invocations
	// nobody can stop — which is all of them but the pull, the one long call
	// this package makes that `K` is offered on (jobs.KindPull.Cancellable).
	// A nil Ctx builds exactly the command it built before.
	Ctx context.Context
}

// dockerRunner is the seam every CLI invocation in this package passes through.
//
// The package talks to the Docker CLI rather than the SDK, which keeps the
// dependency light but makes the whole package untestable without a daemon.
// Routing through this interface lets tests exercise the argument building and
// output parsing — the parts that actually carry defects — against canned
// output.
type dockerRunner interface {
	// LookPath reports whether the docker binary is reachable on PATH.
	LookPath() error
	// Run executes one invocation and returns its captured output.
	Run(cmd dockerCmd) ([]byte, error)
	// Build returns a ready-to-run command without executing it, for callers
	// that hand the process to a terminal (tea.ExecProcess).
	Build(args ...string) *exec.Cmd
}

// cliRunner is the production dockerRunner: it shells out to the real binary.
type cliRunner struct{}

func (cliRunner) LookPath() error {
	_, err := exec.LookPath("docker")
	return err
}

func (cliRunner) Build(args ...string) *exec.Cmd {
	return exec.Command("docker", args...)
}

func (cliRunner) Run(dc dockerCmd) ([]byte, error) {
	name := "docker"
	if dc.Helper != "" {
		name = "docker-credential-" + dc.Helper
	}
	cmd := exec.Command(name, dc.Args...) //nolint:gosec // helper name comes from ~/.docker/config.json
	if dc.Ctx != nil {
		cmd = exec.CommandContext(dc.Ctx, name, dc.Args...) //nolint:gosec // same argument as above
	}
	if dc.Stdin != "" {
		cmd.Stdin = strings.NewReader(dc.Stdin)
	}
	if dc.Combined {
		return cmd.CombinedOutput()
	}
	return cmd.Output()
}

// runner is swapped by tests via stubRunner. Production code never reassigns
// it, so the package stays safe to call concurrently; tests that swap it must
// not run in parallel.
var runner dockerRunner = cliRunner{}

// requireDocker reports the absence of the docker binary with the error message
// callers have always produced.
func requireDocker() error {
	if err := runner.LookPath(); err != nil {
		return fmt.Errorf("docker not found: %w", err)
	}
	return nil
}

// dockerOutput runs `docker args...` and returns stdout only.
func dockerOutput(args ...string) ([]byte, error) {
	return runner.Run(dockerCmd{Args: args})
}

// dockerCombined runs `docker args...` and returns stdout and stderr merged.
func dockerCombined(args ...string) ([]byte, error) {
	return runner.Run(dockerCmd{Args: args, Combined: true})
}

// wrapErr reports a failed invocation whose stderr was not captured, keeping the
// underlying error for errors.Is/As.
func wrapErr(label string, err error) error {
	return fmt.Errorf("%s failed: %w", label, err)
}

// errWithOutput reports a failed invocation using the captured output, which
// carries Docker's own diagnostic.
func errWithOutput(label string, output []byte) error {
	return fmt.Errorf("%s failed: %s", label, strings.TrimSpace(string(output)))
}

// mutate runs a docker subcommand whose output only matters on failure, and
// wraps that output in an error prefixed with label (e.g. "docker stop failed").
//
// It leaves Ctx at its zero value: nothing stops these, which is D7's answer
