package docker

// minShortIDLen is the length of the short container ID printed by `docker ps`.
// maxIDLen is the length of a full SHA-256 container ID.
const (
	minShortIDLen = 12
	maxIDLen      = 64
)

// IsContainerID reports whether s is a well-formed Docker container ID:
// a lowercase hexadecimal string of 12 to 64 characters.
//
// Container IDs are parsed from `docker ps` output and are later embedded in
// shell command lines by the log and inspect pagers. Validating them keeps shell
// metacharacters out of those command lines even if the parsing ever drifts.
func IsContainerID(s string) bool {
	if len(s) < minShortIDLen || len(s) > maxIDLen {
		return false
	}
	for _, r := range s {
		isHex := (r >= '0' && r <= '9') || (r >= 'a' && r <= 'f')
		if !isHex {
			return false
		}
	}
	return true
}
package docker

import "log"

// ImageNames names the images present on this machine, and says whether it
// could find out.
//
// The second return is the whole point. "Docker is not running" and "the image
// is gone" are the same silence from a caller's side, and reading the first as
// the second would empty every cache reader of its images the moment the daemon
// stops. A failed enumeration keeps everything instead: showing a target that no
// longer exists is a stale row, hiding one that does is a lie.
//
// It is a **var**, and that is the test seam three packages were each declaring
// for themselves. A test cannot pull an image, so without it a reconciliation
// could only be asserted by checking that a fixture happens to be absent — which
// it would pass for the wrong reason. Production never reassigns it.
var ImageNames = func() (map[string]struct{}, bool) {
	list, err := ListImages()
	if err != nil {
		log.Printf("INFO [docker] image list unavailable, keeping every cached image: %v", err)
		return nil, false
	}
	names := make(map[string]struct{}, len(list))
	for _, img := range list {
		names[img.Name()] = struct{}{}
	}
	return names, true
}
package docker

import (
	"strconv"
	"strings"
)

// OCIStats contains OCI resource counts and disk usage
type OCIStats struct {
	Available       bool
	ImagesCount     int
	ImagesSize      string
	ContainersCount int
	ContainersSize  string
	VolumesCount    int
	VolumesSize     string

	// NetworksCount does **not** come from `docker system df`, which has no row
	// for networks: they hold no bytes, so the disk report ignores them. It is
	// counted by a separate `docker network ls`, and it is the only figure in
	// this struct that costs a second call.
	NetworksCount int

	// BuildCacheSize is the fourth row `docker system df` prints, and the one
	// that answers "where did the disk go" most often — a build cache commonly
	// reaches tens of gigabytes. It was already part of the reclaimable sum;
	// only its own size used to be discarded.
	BuildCacheSize string

	// Reclaimable is what `docker system df` already reports and this package
	// used to drop on the floor: the space a prune would free, summed across
	// the three families. Docker gives it as "12.3GB (45%)" — only the size
	// is kept, the percentage is relative to its own family and would make no
	// sense once added up.
	Reclaimable string
}

// FetchOCIStats returns OCI resource counts and disk usage via docker system df
func FetchOCIStats() OCIStats {
	stats := OCIStats{}

	if runner.LookPath() != nil {
		return stats
	}

	output, err := dockerOutput("system", "df", "--format",
		"{{.Type}}\t{{.TotalCount}}\t{{.Size}}\t{{.Reclaimable}}")
	if err != nil {
		return stats
	}

	stats.Available = true
	var reclaimable int64

	for _, line := range splitLines(output) {
		parts := strings.SplitN(line, "\t", 4)
		if len(parts) < 3 {
			continue
		}
		count, _ := strconv.Atoi(parts[1])
		size := parts[2]
		if len(parts) >= 4 {
			// "12.3GB (45%)" — the percentage is relative to its own family
			// and would not survive an addition.
			reclaimable += parseSize(strings.TrimSpace(strings.Split(parts[3], "(")[0]))
		}

		switch parts[0] {
		case "Images":
			stats.ImagesCount = count
			stats.ImagesSize = size
		case "Containers":
			stats.ContainersCount = count
			stats.ContainersSize = size
		case "Local Volumes":
			stats.VolumesCount = count
			stats.VolumesSize = size
		case "Build Cache":
			stats.BuildCacheSize = size
		}
	}

	if reclaimable > 0 {
		stats.Reclaimable = formatSize(reclaimable)
	}

	// A list that fails leaves the count at zero rather than failing the
	// whole call: the sizes were just read and are worth returning.
	if networks, err := ListNetworks(); err == nil {
		stats.NetworksCount = len(networks)
	}

	return stats
}
package docker

import (
	"context"
	"fmt"
	"os/exec"
	"strings"
