import "slices"

// Shape is what a backend can express, as opposed to what it is called.
//
// The distinction is the one §3.6 turns on: "Group" against "Organization" is a
// *word*, and words live in the vocabulary. Whether namespaces nest, whether
// `internal` visibility exists, whether a delete can be made permanent — those
// change what the application can promise, and no wording helps with them.
//
// A shape is **declared by the backend**, never sniffed from a URL. That is the
// registry `provider` field's rule (§3.8): a thing is treated as what it says
// it is, so registration order and URL spelling decide nothing.
type Shape struct {
	// Name identifies the backend for a config discriminator and a log line —
	// "gitlab", "github". It is not a display name; that is the vocabulary's.
	Name string

	// MaxNamespaceDepth is how deep namespaces may nest, counting the root as
	// 1. GitHub is 1: an organisation holds repositories and never another
	// organisation. GitLab nests without a documented limit.
	//
	// Zero or less means unbounded. Ask CanNestUnder rather than comparing,
	// so that the sentinel is read in one place instead of at every call site
	// — a `depth < s.MaxNamespaceDepth` written against an unbounded forge is
	// false for every depth, which is the sentinel's whole hazard.
	MaxNamespaceDepth int

	// Visibilities are the values a namespace or repository may take, most
	// private first. GitHub.com has no `internal`, so a form offering three
	// values there offers one that will be refused.
	Visibilities []string

	// PermanentDelete says a deletion can bypass the forge's grace period.
	// GitLab schedules and then permanently removes; GitHub deletes at once and
	// has no equivalent, so the confirmation's "permanent" checkbox is
	// meaningless there and must be out of reach rather than ignored.
	PermanentDelete bool

	// MergedCIConfig says the forge can resolve a repository's CI
	// configuration server-side and hand back the result — every `include` and
	// every component expanded, as the pipeline would actually run.
	//
	// GitLab does it through its lint endpoint. GitHub has no equivalent: a
	// workflow's `uses:` is resolved by the runner at execution time and there
	// is nothing to ask for, so the capability is declared false rather than
	// implemented as something adjacent (the InitialCommit precedent — refuse
	// what the platform cannot express).
	MergedCIConfig bool
}

// CanNestUnder reports whether a namespace may be created under a parent that
// is itself at parentDepth, counting a root namespace as depth 1.
//
// A parentDepth of 0 means "at the root", which every forge allows.
func (s Shape) CanNestUnder(parentDepth int) bool {
	if parentDepth <= 0 {
		return true
	}
	if s.MaxNamespaceDepth <= 0 {
		return true
	}
	return parentDepth < s.MaxNamespaceDepth
}

// AllowsVisibility reports whether v is one this forge accepts. An empty
// Visibilities list allows nothing, which is what an unconfigured backend
// should look like — silently accepting anything is how a form ends up
// offering a value the forge refuses.
func (s Shape) AllowsVisibility(v string) bool {
	return slices.Contains(s.Visibilities, v)
}

// DefaultVisibility is the most private value the forge offers, which is the
// only defensible default: a repository created more open than intended cannot
// be made private again in the eyes of whoever already fetched it.
//
// Empty when the backend declares no visibility at all.
func (s Shape) DefaultVisibility() string {
	if len(s.Visibilities) == 0 {
		return ""
	}
	return s.Visibilities[0]
}
package forge

import "github.com/anthnel/devdesk/internal/config"

// Vocabulary is what a forge is *called*, as opposed to what it can do.
//
// The distinction is §3.6's: "Group" against "Organization" is a **word**,
// while nesting depth and the visibility set are **shapes** — they change what
// the application can promise, and no wording helps with them. Shape carries
// the second; this carries the first, and neither grows conditionals for the
// other.
//
// # Per forge, not neutral
//
// A GitLab user says *group*, a GitHub user says *repository*. "Namespace" is a
// third language nobody speaks, and it makes the application read as an
// abstraction layer rather than as a tool. So every word here is the one its
// forge's own documentation uses.
//
// The field names are neutral because the *code* has to be — a view cannot
// switch on which forge it is talking to — but nothing a user reads is.
//
// # No view writes a forge's name into a string
//
// That is the rule this type exists to make checkable, and
// TestNoViewNamesAForge (internal/ui/vocabtest) walks every string literal
// under internal/ui to enforce it. A command name is not covered: it is routing
// identity, the same for both forges, and lives in internal/command.
type Vocabulary struct {
	// Name is the forge as it names itself — "GitLab", "GitHub". Capitalised:
	// it is a proper noun, and it is what titles and messages interpolate.
	Name string

	// Namespace holds repositories and, on some forges, other namespaces.
	Namespace, Namespaces string

	// Repository is one repository.
	Repository, Repositories string

	// ChangeRequest is a proposal to merge a branch.
	ChangeRequest, ChangeRequests string

	// ChangeRequestShort is the initialism — "MR", "PR". The dashboard's tree
	// nodes are eleven cells wide, so the long form does not fit and truncating
	// it would produce "Merge Req…" on one forge and "Pull Requ…" on the other.
	ChangeRequestShort string

	// TokenLabel is what the auth view calls the secret it asks for.
	TokenLabel string

	// TokenPlaceholder is an example token, shown greyed in the input until the
	// user types.
	//
	// It is a hint and never a check: DevDesk does not validate the prefix, and
	// a forge that changes its format must not turn a working token into a
	// refused one. Shaped like a real value rather than as prose, because that
	// is what a placeholder is — the prose about which prefixes exist lives in
	// TokenHelp, where there is room to name more than one.
	TokenPlaceholder string

	// TokenHelp says where to create a token and which scopes it needs. One
	// sentence, because it is rendered in a help pane beside others.
	TokenHelp string

	// ExampleURL is what the configuration view suggests as a host. The public
	// instance, because it is the only address that is the same for everyone —
	// a self-hosted example would be a hostname nobody has.
	ExampleURL string
}

// gitlabVocabulary and githubVocabulary are the two, written out rather than
// derived: every word is a decision about what that forge's users call things,
// and a rule that produced them would be a rule about English rather than about
// either product.
var (
	gitlabVocabulary = Vocabulary{
		Name:               "GitLab",
		Namespace:          "Group",
		Namespaces:         "Groups",
		Repository:         "Project",
		Repositories:       "Projects",
		ChangeRequest:      "Merge Request",
		ChangeRequests:     "Merge Requests",
		ChangeRequestShort: "MR",
		TokenLabel:         "Personal Access Token",
		TokenPlaceholder:   "glpat-…",
		TokenHelp:          "Create a token in GitLab > Settings > Access Tokens. Required scopes: api, read_user.",
		ExampleURL:         "https://gitlab.com",
	}

	githubVocabulary = Vocabulary{
		Name:               "GitHub",
		Namespace:          "Organization",
		Namespaces:         "Organizations",
		Repository:         "Repository",
		Repositories:       "Repositories",
		ChangeRequest:      "Pull Request",
		ChangeRequests:     "Pull Requests",
		ChangeRequestShort: "PR",
		TokenLabel:         "Personal Access Token",
		TokenPlaceholder:   "ghp_… or github_pat_…",
		TokenHelp:          "Create a token in GitHub > Settings > Developer settings > Personal access tokens. Required scopes: repo, read:org.",
		ExampleURL:         "https://github.com",
	}
)

// VocabularyFor resolves the wording for a configured forge type.
//
// It takes the **configured** type rather than a live Forge, and that is
// deliberate: the explorer's "not authenticated" screen and the auth view's own
// title both need the words before any session exists. A method on Forge would
// be unavailable exactly where the words are needed most.
//
// An unknown type falls back to GitLab rather than to an empty Vocabulary. A
// screen with no nouns on it is a worse failure than a screen using the wrong
// forge's nouns, and config.applyDefaults already guarantees a known value —
// this is the belt to that brace.
func VocabularyFor(forgeType string) Vocabulary {
	switch forgeType {
	case config.ForgeGitHub:
		return githubVocabulary
	default:
		return gitlabVocabulary
	}
}
package forge

import (
	"net/url"
	"strings"

	"github.com/anthnel/devdesk/internal/config"
)

// shapes is what each platform can express. It lives here rather than on each
// backend because a shape is a property of the *platform*, not of a session —
// and the configuration view needs it before any session exists, to know which
// visibilities to offer.
//
// A backend's Shape() answers with its own entry, so there is still one table:
// the interface method exists for a consumer that holds a session and does not
// know the type.
var shapes = map[string]Shape{
	config.ForgeGitLab: {
		Name: config.ForgeGitLab,
		// Unbounded. GitLab documents a limit of 20 on self-managed instances,
		// but it is configurable and the API does not publish it: declaring 20
		// would be asserting what this cannot check, and refusing a legitimate
		// create. The server refuses with its own message instead.
		MaxNamespaceDepth: 0,
		Visibilities:      []string{"private", "internal", "public"},
		PermanentDelete:   true,
		// The lint endpoint returns the resolved configuration.
		MergedCIConfig: true,
	},
	config.ForgeGitHub: {
		Name: config.ForgeGitHub,
		// An organisation never holds an organisation.
		MaxNamespaceDepth: 1,
		// No `internal` on GitHub.com. A form offering it there offers a value
		// the server will refuse.
		Visibilities: []string{"private", "public"},
		// GitHub deletes at once and has no grace period, so there is nothing
		// for a "permanent" checkbox to mean.
		PermanentDelete: false,
		// A workflow's `uses:` is resolved by the runner at execution time;
		// there is no endpoint that hands back an expanded workflow.
		MergedCIConfig: false,
	},
}

// ShapeFor resolves a configured forge type to what it can express.
//
// An unknown type falls back to GitLab's, for VocabularyFor's reason: a screen
// with no visibilities to offer is a worse failure than one offering the wrong
// forge's, and config.applyDefaults already guarantees a known value.
func ShapeFor(forgeType string) Shape {
	if shape, ok := shapes[forgeType]; ok {
		return shape
	}
	return shapes[config.ForgeGitLab]
}

// DetectType guesses a forge from a URL's host, and answers "" when it cannot.
//
// **It only recognises the two public instances.** Self-hosted is the case that
// matters and `git.acme.com` could be either, so anything else is left for the
// user to declare — an unknown host returns "" rather than a default, because a
// wrong guess that looks confident is worse than no guess at all.
//
// Probing was considered and rejected: `/api/v4/version` against `/api/v3/`
// costs a round trip on every keystroke and fails on instances that
// authenticate those endpoints.
func DetectType(rawURL string) string {
	host := hostOf(rawURL)
	if host == "" {
		return ""
	}

	switch {
	case host == "gitlab.com" || strings.HasSuffix(host, ".gitlab.com"):
		return config.ForgeGitLab
	case host == "github.com" || strings.HasSuffix(host, ".github.com"):
		return config.ForgeGitHub
	}
	return ""
}

// hostOf extracts a hostname from what a user may have typed, which is not
// always a URL: `gitlab.com` with no scheme is the common case, and
// url.Parse reads it as a path rather than as a host.
func hostOf(rawURL string) string {
	trimmed := strings.TrimSpace(rawURL)
	if trimmed == "" {
		return ""
	}
	if !strings.Contains(trimmed, "://") {
		trimmed = "https://" + trimmed
	}

	parsed, err := url.Parse(trimmed)
	if err != nil {
		return ""
	}
	return strings.ToLower(parsed.Hostname())
}

